//! Small public BuildHost coverage. Does not claim private report/Kind4 controls ran.
#[path="../../../shared/test_scratch.rs"]mod scratch;
#[path="../../../../analyze/fixtures/native-op-order/fixture.rs"]mod fixture;
use dmbc::{policy_request::{AnalysisContext,PolicyInputRequest,WorkspacePolicyRequest,WorkspaceAuxiliaryQuestion as Q},request::{BuildOutcome,BuildRequest,Command},runner_host::BuildHost};
use std::path::{Path,PathBuf};
fn request(root:&Path)->BuildRequest{let Command::Build(request)=dmbc::cli::parse(&["prepare-query".into(),root.join("deepquarry.dme").to_string_lossy().into_owned()]).unwrap()else{panic!("actual public PrepareQuery")};let mut request=*request;request.no_cache=true;request.exact_inputs=true;request.progress_enabled=false;request.workers=1;request.timeout_seconds=Some(60);request.engine_template=None;request.bootstrap_catalog=false;request.cache_root=Some(root.join("cache"));request.policy_inputs=Some(PolicyInputRequest{analysis_context:Some(AnalysisContext::OriginalAnalyze0290),workspace:Some(WorkspacePolicyRequest{root:root.to_owned(),recursive_roots:vec![root.join("code")],configuration:root.join("tools/ci/lint_scopes.toml")}),workspace_auxiliary:vec![Q::OpOrder],..Default::default()});request}
fn root(label:&str)->PathBuf{let root=scratch::dir(label);for(path,text)in fixture::files("direct",fixture::CASES[0].1){let p=root.join(path);std::fs::create_dir_all(p.parent().unwrap()).unwrap();std::fs::write(p,text).unwrap();}root}
fn prepare(host:&mut BuildHost,request:&BuildRequest)->(String,String){let old_declarations=host.declaration_retention_stats().is_some();let old_prepared=host.prepared_source_retention_census().is_some();let old_symbolic=host.symbolic_retention_stats().is_some();let value=dmbc::request_runner::run_build_with_host(request.clone(),host).unwrap();let BuildOutcome::RawQueryPrepared{source_revision,policy_revision,retained:true,..}=value else{panic!("actual raw-only OpOrder owner missing: {value:?}")};if !old_declarations{assert!(host.declaration_retention_stats().is_none())}if !old_prepared{assert!(host.prepared_source_retention_census().is_none())}if !old_symbolic{assert!(host.symbolic_retention_stats().is_none())}(source_revision,policy_revision)}
#[test]fn actual_public_op_order_accepts_only_raw_manifest_outcomes_without_creating_a_frontend(){for kind in 0..3{let root=root("public-op-order-raw-manifest");match kind{0=>{},1=>std::fs::remove_file(root.join("deepquarry.dme")).unwrap(),2=>std::fs::write(root.join("deepquarry.dme"),[0xff,0xfe,0x80]).unwrap(),_=>unreachable!()}let mut host=BuildHost::default();prepare(&mut host,&request(&root));assert!(!root.join("deepquarry.dmb").exists());assert!(!root.join("deepquarry.rsc").exists());}}
#[test]fn actual_public_op_order_manifest_uncompiled_file_and_config_revisions_reissue_the_same_host(){let root=root("public-op-order-revisions");let request=request(&root);let mut host=BuildHost::default();let first=prepare(&mut host,&request);assert_eq!(prepare(&mut host,&request),first);std::fs::write(root.join("deepquarry.dme"),"#include \"code/uncompiled-later.dm\"\n").unwrap();let manifest=prepare(&mut host,&request);assert_ne!(manifest.0,first.0);std::fs::write(root.join("code/uncompiled-later.dm"),"CAPABILITIES(/obj/later,op(\"a\",hand()),op(\"b\",hand()))\n").unwrap();let source=prepare(&mut host,&request);assert_ne!(source.0,manifest.0);std::fs::remove_file(root.join("code/uncompiled-later.dm")).unwrap();let removed=prepare(&mut host,&request);assert_ne!(removed.0,source.0);std::fs::write(root.join("tools/ci/lint_scopes.toml"),"[lint.op_order]\nexempt_files=[\"code/probe.dm\"]\n").unwrap();let configured=prepare(&mut host,&request);assert_ne!(configured.1,removed.1);}
#[test]fn actual_public_op_order_operational_manifest_failure_is_not_an_empty_order_and_recovers(){let root=root("public-op-order-manifest-failure");let request=request(&root);let mut host=BuildHost::default();prepare(&mut host,&request);let path=root.join("deepquarry.dme");std::fs::remove_file(&path).unwrap();std::fs::create_dir(&path).unwrap();assert!(dmbc::request_runner::run_build_with_host(request.clone(),&mut host).is_err(),"typed provider IO cannot be replaced with an authentic missing/invalid UTF8 observation");std::fs::remove_dir(&path).unwrap();std::fs::write(&path,"malformed but readable manifest\n").unwrap();prepare(&mut host,&request);}
